    if ((temperature == NULL) || (voltage == NULL) || (resistance == NULL) ||
        (next_temperature == NULL) || (current == NULL) || (power == NULL) ||
        (total_power == NULL)) {
        return ADCS_E_NULL;
    }

    // Check finiteness of all input components and ambient
    if ((!isfinite(voltage->x)) || (!isfinite(voltage->y)) || (!isfinite(voltage->z)) ||
        (!isfinite(resistance->x)) || (!isfinite(resistance->y)) || (!isfinite(resistance->z)) ||
        (!isfinite(temperature->x)) || (!isfinite(temperature->y)) || (!isfinite(temperature->z)) ||
        (!isfinite(ambient))) {
        return ADCS_E_RANGE;
    }

    // Check resistances are positive
    if ((resistance->x <= 0.0) || (resistance->y <= 0.0) || (resistance->z <= 0.0)) {
        return ADCS_E_RANGE;
    }

    // Check thermal parameters and dt
    if ((!isfinite(thermal_capacity)) || (thermal_capacity <= 0.0) ||
        (!isfinite(thermal_resistance)) || (thermal_resistance <= 0.0) ||
        (!isfinite(dt)) || (dt < 0.0)) {
        return ADCS_E_RANGE;
    }

    // Compute Currents: I = V / R
    current->x = voltage->x / resistance->x;
    current->y = voltage->y / resistance->y;
    current->z = voltage->z / resistance->z;

    // Compute Powers: P = V^2 / R
    power->x = (voltage->x * voltage->x) / resistance->x;
    power->y = (voltage->y * voltage->y) / resistance->y;
    power->z = (voltage->z * voltage->z) / resistance->z;

    // Total Power
    *total_power = power->x + power->y + power->z;

    // Update Temperatures: T_next = T + dt * (P - (T - ambient) / R_th) / C_th
    double inv_rc = 1.0 / (thermal_capacity * thermal_resistance);
    double coeff = dt * inv_rc;

    next_temperature->x = temperature->x + coeff * (power->x - (temperature->x - ambient) / thermal_resistance);
    next_temperature->y = temperature->y + coeff * (power->y - (temperature->y - ambient) / thermal_resistance);
    next_temperature->z = temperature->z + coeff * (power->z - (temperature->z - ambient) / thermal_resistance);

    return ADCS_OK;
}

