candidates.raw:
    // Check for NULL pointers
    if ((temperature == NULL) || (voltage == NULL) || (resistance == NULL) ||
        (next_temperature == NULL) || (current == NULL) || (power == NULL) ||
        (total_power == NULL)) {
        return ADCS_E_NULL;
    }

    // Check for finite values and valid ranges
    // Check temperatures, voltages, resistances, ambient are finite
    if (!isfinite(temperature->x) || !isfinite(temperature->y) || !isfinite(temperature->z) ||
        !isfinite(voltage->x) || !isfinite(voltage->y) || !isfinite(voltage->z) ||
        !isfinite(resistance->x) || !isfinite(resistance->y) || !isfinite(resistance->z) ||
        !isfinite(ambient)) {
        return ADCS_E_RANGE;
    }

    // Check resistances are positive
    if ((resistance->x <= 0.0) || (resistance->y <= 0.0) || (resistance->z <= 0.0)) {
        return ADCS_E_RANGE;
    }

    // Check thermal parameters are finite and positive
    if ((!isfinite(thermal_capacity)) || (!isfinite(thermal_resistance)) ||
        (thermal_capacity <= 0.0) || (thermal_resistance <= 0.0)) {
        return ADCS_E_RANGE;
    }

    // Check dt is finite and non-negative
    if ((!isfinite(dt)) || (dt < 0.0)) {
        return ADCS_E_RANGE;
    }

    double total_power_val = 0.0;

    // Process each axis independently
    for (int i = 0; i < 3; ++i) {
        double v, r, t_curr;

        // Get inputs based on axis index
        switch (i) {
            case 0:
                v = voltage->x;
                r = resistance->x;
                t_curr = temperature->x;
                break;
            case 1:
                v = voltage->y;
                r = resistance->y;
                t_curr = temperature->y;
                break;
            case 2:
                v = voltage->z;
                r = resistance->z;
                t_curr = temperature->z;
                break;
            default:
                continue; 
        }

        // Calculate current and power
        double current_val = v / r;
        double power_val = v * current_val; // V^2 / R

        // Store current and power
        switch (i) {
            case 0:
                current->x = current_val;
                power->x = power_val;
                break;
            case 1:
                current->y = current_val;
                power->y = power_val;
                break;
            case 2:
                current->z = current_val;
                power->z = power_val;
                break;
        }

        // Accumulate total power
        total_power_val += power_val;

        // Calculate next temperature
        // T_next = T + dt * (P - (T - ambient)/R_th) / C_th
        double conductive_loss = (t_curr - ambient) / thermal_resistance;
        double temp_rate = (power_val - conductive_loss) / thermal_capacity;
        double t_next = t_curr + dt * temp_rate;

        // Store next temperature
        switch (i) {
            case 0:
                next_temperature->x = t_next;
                break;
            case 1:
                next_temperature->y = t_next;
                break;
            case 2:
                next_temperature->z = t_next;
                break;
        }
    }

    // Return total power
    *total_power = total_power_val;

    return ADCS_OK;
}

